import pathlib
H = pathlib.Path(__file__).resolve().parent
p = H / 'assets_jb.js'; t = p.read_text(encoding='utf8'); assert 'const cashArt' not in t
add = r'''  // ===== CASH ART (2D drawn, shaded to read as 3D objects; shown on a Card kind:'paint' so it sits in the 3D scene). Use instead of cylinder "bags". docs/JC_DEPICTION_MAP.md =====
  const cashBill = (g, x, y, w, h, rot, a) => { g.save(); g.translate(x, y); g.rotate(rot || 0); g.globalAlpha = a === undefined ? 1 : a; g.fillStyle = '#2E6B3F'; rrect(g, -w / 2, -h / 2 + h * 0.13, w, h, h * 0.12); g.fill(); g.fillStyle = '#7CCB7A'; rrect(g, -w / 2, -h / 2, w, h, h * 0.12); g.fill(); g.lineWidth = Math.max(1.5, h * 0.06); g.strokeStyle = '#245B33'; g.stroke(); g.strokeStyle = '#E6F5D6'; g.lineWidth = h * 0.035; g.strokeRect(-w * 0.43, -h * 0.36, w * 0.86, h * 0.72); g.beginPath(); g.arc(0, 0, h * 0.29, 0, 7); g.fillStyle = '#D6EFC0'; g.fill(); g.lineWidth = h * 0.05; g.stroke(); g.fillStyle = '#245B33'; g.font = '900 ' + h * 0.42 + 'px' + FAM; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText('$', 0, h * 0.03); g.restore(); };
  const cashStack = (g, cx, by, w, layers) => { const lh = w * 0.075, h = layers * lh, d = w * 0.3, dy = d * 0.55; g.save(); g.lineJoin = 'round'; g.lineWidth = Math.max(2, w * 0.016); g.strokeStyle = '#1F4D2D';
    g.fillStyle = '#2F7A45'; g.beginPath(); g.moveTo(cx + w / 2, by); g.lineTo(cx + w / 2 + d, by - dy); g.lineTo(cx + w / 2 + d, by - h - dy); g.lineTo(cx + w / 2, by - h); g.closePath(); g.fill(); g.stroke();
    const gr = g.createLinearGradient(0, by - h, 0, by); gr.addColorStop(0, '#68C47B'); gr.addColorStop(1, '#3E9558'); g.fillStyle = gr; g.fillRect(cx - w / 2, by - h, w, h); g.strokeRect(cx - w / 2, by - h, w, h);
    g.lineWidth = Math.max(1, w * 0.008); g.strokeStyle = 'rgba(20,70,35,0.55)'; for (let i = 1; i < layers; i++) { g.beginPath(); g.moveTo(cx - w / 2, by - h + i * lh); g.lineTo(cx + w / 2, by - h + i * lh); g.stroke(); }
    g.lineWidth = Math.max(2, w * 0.016); g.strokeStyle = '#1F4D2D'; g.fillStyle = '#EAD9A0'; g.fillRect(cx - w * 0.11, by - h, w * 0.22, h); g.strokeRect(cx - w * 0.11, by - h, w * 0.22, h); g.fillStyle = '#7A6A2A'; g.font = '900 ' + Math.min(h * 0.6, w * 0.22) + 'px' + FAM; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText('$', cx, by - h / 2 + w * 0.005);
    g.fillStyle = '#9BE3A8'; g.beginPath(); g.moveTo(cx - w / 2, by - h); g.lineTo(cx - w / 2 + d, by - h - dy); g.lineTo(cx + w / 2 + d, by - h - dy); g.lineTo(cx + w / 2, by - h); g.closePath(); g.fill(); g.stroke(); g.restore(); };
  const cashBag = (g, cx, by, s) => { g.save(); g.lineJoin = 'round'; g.lineWidth = Math.max(2, s * 0.035); g.strokeStyle = '#5E3F12'; g.beginPath(); g.moveTo(cx - s * 0.15, by - s * 0.7); g.bezierCurveTo(cx - s * 0.7, by - s * 0.42, cx - s * 0.62, by + 0.0, cx - s * 0.36, by); g.lineTo(cx + s * 0.36, by); g.bezierCurveTo(cx + s * 0.62, by, cx + s * 0.7, by - s * 0.42, cx + s * 0.15, by - s * 0.7); g.closePath();
    const gr = g.createRadialGradient(cx - s * 0.18, by - s * 0.38, s * 0.05, cx, by - s * 0.3, s * 0.7); gr.addColorStop(0, '#F3D888'); gr.addColorStop(1, '#B98A2E'); g.fillStyle = gr; g.fill(); g.stroke();
    g.fillStyle = '#8A5A1E'; rrect(g, cx - s * 0.2, by - s * 0.78, s * 0.4, s * 0.1, s * 0.03); g.fill(); g.stroke(); g.beginPath(); g.moveTo(cx - s * 0.2, by - s * 0.78); g.lineTo(cx - s * 0.32, by - s * 0.95); g.lineTo(cx - s * 0.08, by - s * 0.8); g.closePath(); g.moveTo(cx + s * 0.2, by - s * 0.78); g.lineTo(cx + s * 0.32, by - s * 0.95); g.lineTo(cx + s * 0.08, by - s * 0.8); g.closePath(); g.fillStyle = '#C99A3E'; g.fill(); g.stroke();
    g.fillStyle = '#5E3F12'; g.font = '900 ' + s * 0.5 + 'px' + FAM; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText('$', cx, by - s * 0.3); g.fillStyle = 'rgba(255,255,255,0.28)'; g.beginPath(); g.ellipse(cx - s * 0.3, by - s * 0.4, s * 0.07, s * 0.2, 0.3, 0, 7); g.fill(); g.restore(); };
  const cashFlame = (g, cx, by, s, tt, seed) => { g.save(); [['#E8553A', 1.0], ['#F2A33A', 0.78], ['#FFE48A', 0.5]].forEach(([col, k], i) => { const sw = Math.sin(tt * 9 + seed + i) * s * 0.07, hh = s * k * (0.9 + 0.12 * Math.sin(tt * 12 + seed * 2 + i)); g.beginPath(); g.moveTo(cx - s * 0.32 * k, by); g.bezierCurveTo(cx - s * 0.4 * k, by - hh * 0.5, cx - s * 0.06 + sw, by - hh * 0.65, cx + sw, by - hh); g.bezierCurveTo(cx + s * 0.06 + sw, by - hh * 0.65, cx + s * 0.4 * k, by - hh * 0.5, cx + s * 0.32 * k, by); g.closePath(); g.fillStyle = col; g.fill(); });
    for (let i = 0; i < 5; i++) { const q = (tt * 0.9 + i * 0.21 + seed) % 1; g.globalAlpha = 1 - q; g.fillStyle = '#FFC857'; g.beginPath(); g.arc(cx + Math.sin(i * 2.3 + seed) * s * 0.4, by - s * (0.6 + q * 0.9), s * 0.035, 0, 7); g.fill(); } g.restore(); };
  // cashArt(g, pw, ph, items, t): items = [{k:'stack'|'bag', x, y (baseline) as fractions of pw/ph, s (size, fraction of pw), n (stack layers), t0 (pops in), burn:[t0,t1] (flames, the pile blackens and shrinks to ash), out:[t0,t1] (fades away), sx (x-squash 0..1)}]
  const cashArt = (g, pw, ph, items, t) => items.forEach((it, i) => { const u = seg(t, it.t0 === undefined ? -9 : it.t0, (it.t0 === undefined ? -9 : it.t0) + 0.4); if (u <= 0) return; const bp = it.burn ? seg(t, it.burn[0], it.burn[1]) : 0, fo = it.out ? 1 - seg(t, it.out[0], it.out[1]) : 1; if (fo <= 0.01) return;
    const sc = (0.7 + 0.3 * Math.sin(u * 1.57)) * (1 - 0.8 * bp), cx = it.x * pw, by = it.y * ph, S = it.s * pw * sc; g.save(); g.globalAlpha = u * fo; g.translate(cx, by); g.scale(it.sx === undefined ? 1 : it.sx, 1); g.translate(-cx, -by);
    g.shadowColor = 'rgba(0,0,0,0.28)'; g.shadowBlur = pw * 0.02; g.shadowOffsetY = pw * 0.012; if (it.k === 'bag') cashBag(g, cx, by, S); else cashStack(g, cx, by, S, it.n || 8); g.shadowColor = 'transparent';
    if (bp > 0) { g.fillStyle = 'rgba(25,18,12,' + (0.55 * Math.min(1, bp * 2)) + ')'; g.fillRect(cx - S * 0.7, by - S * 1.1, S * 1.4, S * 1.1); }
    if (bp > 0 && bp < 1) cashFlame(g, cx, by, S * 1.3 * (1 - 0.4 * bp) + pw * 0.04, t, i * 1.7); if (bp >= 1) { g.fillStyle = '#3A3A3A'; g.beginPath(); g.ellipse(cx, by - pw * 0.005, pw * 0.05, pw * 0.014, 0, 0, 7); g.fill(); } g.restore(); });
'''
i = t.index("  const pad = (x0, z0, x1, z1, col)"); p.write_text(t[:i] + add + t[i:], encoding='utf8'); print('cash art ok')
